import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static long[][] f = new long[30][MAXN];
    static long[] fac = new long[MAXN];
    static long[] inv = new long[MAXN];
    static int[] a = new int[55];
    static int[] S = new int[1 << 20]; // N <= 2^20
    static int[] p = new int[1 << 20];
    static int n, k, MO, s, N;

    static long pw(long x, int y) {
        long t = 1;
        while (y > 0) {
            if ((y & 1) == 1) t = t * x % MO;
            x = x * x % MO;
            y >>= 1;
        }
        return t;
    }

    static long P(int x, int y) {
        return fac[x] * inv[x - y] % MO;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        MO = sc.nextInt();
        sc.close();

        if ((n & 1) == 1) {
            System.out.println(pw(k, n));
            return;
        }

        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MO;
        }
        inv[n] = pw(fac[n], MO - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = inv[i + 1] * (i + 1) % MO;
        }

        int t = n;
        s = 0;
        for (int i = 0; i <= 20; i++) {
            if ((t & 1) == 1) a[s++] = 1 << i;
            t >>= 1;
        }
        N = 1 << s;
        for (int i = 0; i < N; i++) {
            int sum = 0;
            for (int j = 0; j < s; j++) {
                if (((i >> j) & 1) == 1) sum += a[j];
            }
            S[i] = sum;
        }
        for (int i = 0; i < N; i++) {
            int highest = -1;
            for (int j = 0; j <= 20; j++) {
                if (((i >> j) & 1) == 1) highest = j;
            }
            p[i] = (1 << (highest + 1)) + i;
        }

        f[0][0] = 1;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < N; j++) {
                if (f[i][j] != 0) {
                    for (int kk = p[j]; kk < N; kk = (kk + 1) | j) {
                        f[i + 1][kk] = (f[i + 1][kk] + f[i][j] * inv[S[kk ^ j]]) % MO;
                    }
                }
            }
        }

        long ans = 0;
        for (int i = 0; i <= k; i++) {
            ans = (ans + f[i][N - 1] * P(k, i)) % MO;
        }
        ans = ans * fac[n] % MO;
        ans = (pw(k, n) - ans + MO) % MO;
        System.out.println(ans);
    }
}
